insert into public.website_chatbot_faqs(question,keywords,answer,is_active) select 'হলুদ ও মুসলিম বিয়ের প্রাথমিক কোটেশন',array['হলুদ বিয়ে মুসলিম','holud wedding muslim'],'ময়মনসিংহে একই প্রাথমিক কোটেশনে দুটি অনুষ্ঠান হলে: Essential ৳১৩,৯৯৮; Signature ৳২৩,৯৯৮; Premium ৳৩৭,৯৯৮। এটি আলোচনার কোটেশন; সময়, সুবিধা ও ট্রাভেল অফিস নিশ্চিত করবে। আলোচনার ফর্ম: /booking?intent=discussion',true where not exists(select 1 from public.website_chatbot_faqs where question='হলুদ ও মুসলিম বিয়ের প্রাথমিক কোটেশন');
insert into public.website_chatbot_faqs(question,keywords,answer,is_active) select 'শুধু কনে বা বরের ছবি',array['bride only','groom only','শুধু কনের','শুধু বরের'],'বর-কনের পোর্ট্রেট ও কাপল ছবি রাখা যাবে 📸 কোন অনুষ্ঠান ও কতক্ষণ শুট চান? আলোচনা: /booking?intent=discussion',true where not exists(select 1 from public.website_chatbot_faqs where question='শুধু কনে বা বরের ছবি');
insert into public.website_chatbot_faqs(question,keywords,answer,is_active) select 'ফটোগ্রাফি টিম কতজন',array['team size','টিম কয়জন','টিম কতজন','team কয়জন'],'টিমের সংখ্যা প্যাকেজ অনুযায়ী। প্রয়োজন হলে বাড়ানো-কমানো নিয়ে আলোচনা করা যাবে। কোন প্যাকেজটি ভাবছেন? /packages',true where not exists(select 1 from public.website_chatbot_faqs where question='ফটোগ্রাফি টিম কতজন');
insert into public.website_chatbot_faqs(question,keywords,answer,is_active) select 'এডিট করা ছবি পাবেন কি',array['edited photos','এডিট ছবি','edited photo','এডিটেড'],'প্যাকেজে উল্লেখিত এডিট করা ছবি পাবেন। ছবির সংখ্যা ও এডিটিংয়ের ধরন নির্বাচিত প্যাকেজে দেখে নিন। কোন প্যাকেজ চান? /packages',true where not exists(select 1 from public.website_chatbot_faqs where question='এডিট করা ছবি পাবেন কি');
insert into public.website_chatbot_faqs(question,keywords,answer,is_active) select 'RAW ছবি প্রয়োজন',array['raw','র ফাইল','র ছবি','রও ছবি'],'RAW ফাইল লাগলে বুকিংয়ের আগে জানান। নিজের স্টোরেজ/ড্রাইভের ব্যবস্থা ও ফাইল দেওয়ার শর্ত অফিসের সঙ্গে নিশ্চিত করুন। /booking?intent=discussion',true where not exists(select 1 from public.website_chatbot_faqs where question='RAW ছবি প্রয়োজন');
insert into public.website_chatbot_faqs(question,keywords,answer,is_active) select 'ছবির ডেলিভারির সময়',array['photo delivery','ছবির ডেলিভারি','ছবি কবে','ছবি কত দিনে'],'এডিট ছবির প্রাথমিক সময়সীমা সর্বোচ্চ ১০ কর্মদিবস। অনুষ্ঠান ও সার্ভিস অনুযায়ী চূড়ান্ত সময় অফিস নিশ্চিত করবে। আপনার অনুষ্ঠান কবে?',true where not exists(select 1 from public.website_chatbot_faqs where question='ছবির ডেলিভারির সময়');
insert into public.website_chatbot_faqs(question,keywords,answer,is_active) select 'ভিডিও ডেলিভারির সময়',array['video delivery','ভিডিও কবে','ভিডিও ডেলিভারি'],'ভিডিও এডিট ও ডেলিভারির প্রাথমিক সময়সীমা সর্বোচ্চ ৪৫ কর্মদিবস। নির্বাচিত সার্ভিস অনুযায়ী চূড়ান্ত সময় অফিস নিশ্চিত করবে।',true where not exists(select 1 from public.website_chatbot_faqs where question='ভিডিও ডেলিভারির সময়');
insert into public.website_chatbot_faqs(question,keywords,answer,is_active) select 'বুকিংয়ের তারিখ বদলানো',array['date change','তারিখ বদল','তারিখ পরিবর্তন'],'নতুন তারিখে টিম ফাঁকা থাকলে পরিবর্তন করা যেতে পারে। আগে অফিসের অনুমোদন নিন। নতুন তারিখ কবে? /booking?intent=discussion',true where not exists(select 1 from public.website_chatbot_faqs where question='বুকিংয়ের তারিখ বদলানো');
insert into public.website_chatbot_faqs(question,keywords,answer,is_active) select 'বুকিং বাতিলের নিয়ম',array['cancel','বাতিল','refund','রিফান্ড'],'অগ্রিম ফেরত বা তারিখ পরিবর্তনের বিষয়টি আপনার চুক্তির শর্ত ও অফিসের যাচাই অনুযায়ী হবে। রিফান্ড নিশ্চিত করে বলছি না। অফিসে কথা বলুন: /booking?intent=discussion',true where not exists(select 1 from public.website_chatbot_faqs where question='বুকিং বাতিলের নিয়ম');
insert into public.website_chatbot_faqs(question,keywords,answer,is_active) select 'হিন্দু বিয়ের Essential সুবিধা',array['hindu essential','হিন্দু এসেনশিয়াল'],'ময়মনসিংহে হিন্দু বিয়ের Essential প্রাথমিক কোটেশন ৳২৩,৯৯৮, মূলত ফটোগ্রাফি। রীতিনীতি ও সময় দেখে সঠিক কভারেজ অফিস জানাবে। অনুষ্ঠান কখন শুরু ও শেষ হবে? /booking?intent=discussion',true where not exists(select 1 from public.website_chatbot_faqs where question='হিন্দু বিয়ের Essential সুবিধা');
insert into public.website_chatbot_faqs(question,keywords,answer,is_active) select 'হিন্দু বিয়ের Signature সুবিধা',array['hindu signature','হিন্দু সিগনেচার'],'ময়মনসিংহে হিন্দু বিয়ের Signature প্রাথমিক কোটেশন ৳৩২,০০০। গুরুত্বপূর্ণ রীতিনীতি ও মুহূর্তের কভারেজ সময়সূচি অনুযায়ী ঠিক হবে। আপনার অনুষ্ঠানের সময়সূচি কী? /booking?intent=discussion',true where not exists(select 1 from public.website_chatbot_faqs where question='হিন্দু বিয়ের Signature সুবিধা');
insert into public.website_chatbot_faqs(question,keywords,answer,is_active) select 'হিন্দু বিয়ের Premium সুবিধা',array['hindu premium','হিন্দু প্রিমিয়াম'],'ময়মনসিংহে হিন্দু বিয়ের Premium প্রাথমিক কোটেশন ৳৪২,০০০: ফটোগ্রাফি ও সিনেমাটিক ভিডিও। সময়, টিম ও অন্তর্ভুক্ত অনুষ্ঠান অফিস নিশ্চিত করবে। /booking?intent=discussion',true where not exists(select 1 from public.website_chatbot_faqs where question='হিন্দু বিয়ের Premium সুবিধা');
insert into public.website_chatbot_faqs(question,keywords,answer,is_active) select 'তিন দিনের অনুষ্ঠান',array['তিন দিনের','3 days','তিনদিন'],'তিন দিনের প্রতিটি অনুষ্ঠানের নাম, তারিখ, শুরু-শেষের সময় ও লোকেশন দিন। একই কোটেশনে সবগুলো রাখা যাবে; অফিস চূড়ান্ত করবে। /booking?intent=discussion',true where not exists(select 1 from public.website_chatbot_faqs where question='তিন দিনের অনুষ্ঠান');
insert into public.website_chatbot_faqs(question,keywords,answer,is_active) select 'পরিবারের ছবির অনুরোধ',array['family photo','পরিবারের ছবি','গ্রুপ ছবি'],'পরিবারের গ্রুপ ছবি ও গুরুত্বপূর্ণ মানুষদের মুহূর্তের নোট বুকিংয়ে দিতে পারবেন। কার কার ছবি বিশেষভাবে দরকার জানাবেন। /booking',true where not exists(select 1 from public.website_chatbot_faqs where question='পরিবারের ছবির অনুরোধ');
insert into public.website_chatbot_faqs(question,keywords,answer,is_active) select 'মানুষের সহায়তা',array['মানুষের সাহায্য','human','ফোন নম্বর','যোগাযোগ'],'অফিসে সরাসরি কথা বলুন: 01776044951 · WhatsApp https://wa.me/8801776044951। প্যাকেজ বা বুকিংয়ের আলোচনাও দিতে পারেন: /booking?intent=discussion',true where not exists(select 1 from public.website_chatbot_faqs where question='মানুষের সহায়তা');
insert into public.website_chatbot_faqs(question,keywords,answer,is_active) select 'ফলোআপ টেমপ্লেট ১',array['followup 1','ফলোআপ ১'],'হ্যালো 🌸 আপনার আয়োজনের প্যাকেজ নিয়ে কোনো প্রশ্ন আছে? তারিখ ও লোকেশন জানালে উপযুক্ত কভারেজ নিয়ে আলোচনা করতে পারি। /booking?intent=discussion',true where not exists(select 1 from public.website_chatbot_faqs where question='ফলোআপ টেমপ্লেট ১');
insert into public.website_chatbot_faqs(question,keywords,answer,is_active) select 'ফলোআপ টেমপ্লেট ২',array['followup 2','ফলোআপ ২'],'ছবি, ভিডিও, সময় বা বাজেটের কোন বিষয়টি জানতে চান? আপনার প্রয়োজন অনুযায়ী অপশন দেখে নিন। /packages',true where not exists(select 1 from public.website_chatbot_faqs where question='ফলোআপ টেমপ্লেট ২');
insert into public.website_chatbot_faqs(question,keywords,answer,is_active) select 'শেষ ফলোআপের টেমপ্লেট',array['final followup','শেষ ফলোআপ'],'আপনার আয়োজন নিয়ে সিদ্ধান্ত হলে তারিখ ও লোকেশন পাঠাতে পারেন। প্রয়োজন হলে প্যাকেজ ও বুকিংয়ে সাহায্য করব। /booking?intent=discussion',true where not exists(select 1 from public.website_chatbot_faqs where question='শেষ ফলোআপের টেমপ্লেট');
